use xiom.io;

type Rectangle = {
  width: Float64;
  height: Float64;
  invariant: width > 0.0;
  invariant: height > 0.0;
}

fn Rectangle.area(self) -> Float64
  ensures: result > 0.0;
{
  return self.width * self.height;
}

fn Rectangle.perimeter(self) -> Float64
  ensures: result > 0.0;
{
  return 2.0 * (self.width + self.height);
}

fn Rectangle.is_square(self) -> Bool {
  return self.width == self.height;
}

fn Rectangle.scale(&mut self, factor: Float64)
  requires: factor > 0.0;
{
  self.width = self.width * factor;
  self.height = self.height * factor;
}

fn main() -> Int {
  var r: Rectangle = Rectangle{ width: 5.0, height: 10.0 };
  io.println("Area: " + r.area().to_str());
  io.println("Perimeter: " + r.perimeter().to_str());
  io.println("Is square: " + r.is_square().to_str());
  r.scale(2.0);
  io.println("New area: " + r.area().to_str());
  return 0;
}
